import os, json, pathlib
pd = pathlib.Path(os.environ['LOCKSTEP_PHASE_DIR'])
vf = pd.parent / 'scope-probe' / 'verdicts.jsonl'
records = []
if vf.exists():
    for l in vf.read_text(encoding='utf-8', errors='replace').splitlines():
        if not l.strip():
            continue
        try:
            records.append(json.loads(l))
        except ValueError:
            records.append({'malformed': l[:200]})
esc = pathlib.Path('pi-guard-escape.tmp')
escaped = esc.exists()
if escaped:
    try:
        esc.unlink()
    except OSError:
        pass
findings = []
if not records:
    findings.append({'severity': 'blocker', 'category': 'guard-missing', 'file': '.pi/extensions/lockstep-guard.ts', 'line': None, 'claim': 'no block verdict was recorded - extension not loaded or tool_call API drifted', 'evidence': 'verdicts.jsonl absent or empty in the scope-probe phase dir', 'fix_hint': 'confirm the extension file is in .pi/extensions/ and the pi version still fires tool_call hooks'})
if escaped:
    findings.append({'severity': 'blocker', 'category': 'guard-bypassed', 'file': 'pi-guard-escape.tmp', 'line': None, 'claim': 'the out-of-scope write landed on disk (removed by this gate)', 'evidence': 'pi-guard-escape.tmp existed at the repo root', 'fix_hint': 'guard did not block; verify insideScope() and LOCKSTEP_WORKSPACE_SCOPE'})
verdict = 'pass' if not findings else 'block'
reason = 'guard blocked the escape and recorded ' + str(len(records)) + ' verdict record(s)' if verdict == 'pass' else str(len(findings)) + ' guard failure(s)'
print(json.dumps({'findings': findings, 'verdict': verdict, 'reason': reason}))

